<?php
require_once __DIR__ . '/bootstrap.php';
function upload_tour_image(string $field,int $tourId,string $kind): string {
 if(empty($_FILES[$field]) || (int)$_FILES[$field]['error']===UPLOAD_ERR_NO_FILE) return '';
 $f=$_FILES[$field]; if((int)$f['error']!==UPLOAD_ERR_OK) throw new RuntimeException('Could not upload the '.$kind.' image.');
 if((int)$f['size']>5*1024*1024) throw new RuntimeException('The '.$kind.' image must be 5 MB or smaller.');
 $info=@getimagesize((string)$f['tmp_name']); if(!$info) throw new RuntimeException('The '.$kind.' file is not a valid image.');
 $mime=(string)($info['mime']??''); $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']; if(!isset($allowed[$mime])) throw new RuntimeException('The '.$kind.' must be JPG, PNG or WebP.');
 $minW=$kind==='cover'?1200:200; $minH=$kind==='cover'?450:60; if((int)$info[0]<$minW||(int)$info[1]<$minH) throw new RuntimeException(ucfirst($kind).' image must be at least '.$minW.' × '.$minH.' px.');
 $baseDir=__DIR__.'/uploads/tours'; $dir=$baseDir.'/'.$tourId; if(!is_dir($baseDir) && !@mkdir($baseDir,0775,true) && !is_dir($baseDir)) throw new RuntimeException('Image upload base directory is not writable: '.saas_h($baseDir)); if(!is_dir($dir) && !@mkdir($dir,0775,true) && !is_dir($dir)){ $parent=is_dir($baseDir)?$baseDir:dirname($baseDir); throw new RuntimeException('Could not create image upload directory. Path: '.$dir.' | Parent writable: '.(is_writable($parent)?'YES':'NO').' | Base writable: '.(is_writable($baseDir)?'YES':'NO')); } if(!is_writable($dir)) throw new RuntimeException('Image upload directory is not writable: '.$dir);
 $name=$kind.'-'.bin2hex(random_bytes(8)).'.'.$allowed[$mime]; if(!move_uploaded_file((string)$f['tmp_name'],$dir.'/'.$name)) throw new RuntimeException('Could not save the '.$kind.' image.');
 return '/uploads/tours/'.$tourId.'/'.$name;
}
saas_require_organization(); saas_require_permission('tour.create');
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 saas_check_csrf(); $orgId=saas_current_organization_id(); $name=trim((string)($_POST['name']??'')); $slugInput=trim((string)($_POST['slug']??'')); $slug=saas_slug($slugInput!==''?$slugInput:$name); $start=trim((string)($_POST['start_date']??'')); $end=trim((string)($_POST['end_date']??'')); $fee=max(0,(float)($_POST['default_fee']??0)); $desc=trim((string)($_POST['description']??'')); $transport=strtoupper(trim((string)($_POST['default_transport']??'BUS'))); $banner='';$logo='';$departures=array_values(array_filter(array_map('trim',preg_split('/\R+/',(string)($_POST['departure_options']??'')))));
 if($name==='') $error='Tour name is required.'; elseif(!preg_match('/^[a-z0-9][a-z0-9-]{1,178}$/',$slug)) $error='Public slug must use lowercase letters, numbers and hyphens only.'; elseif(in_array($slug,['saas-dashboard','saas-public','public-tour','index'],true)) $error='That public slug is reserved. Please choose another one.'; elseif($start!==''&&$end!==''&&$end<$start) $error='End date cannot be before start date.'; elseif(!in_array($transport,['BUS','TRAIN','LAUNCH','AIR','OTHER','NONE'],true)) $error='Invalid default transport.'; else try{
  $db=saas_db(); $db->beginTransaction(); $q=$db->prepare('SELECT id FROM organizations WHERE id=? FOR UPDATE'); $q->execute([$orgId]); if(!$q->fetch()) throw new RuntimeException('Organization not found.'); $q=$db->prepare('SELECT COUNT(*) FROM tours WHERE organization_id=?'); $q->execute([$orgId]); $currentTours=(int)$q->fetchColumn(); saas_require_limit($orgId,'max_tours',$currentTours,'Your current plan has reached its tour limit. Open Billing to upgrade your plan.'); if($slugInput===''){ $baseSlug=$slug; $candidate=$baseSlug; for($n=2;;$n++){ $q=$db->prepare('SELECT id FROM tours WHERE organization_id=? AND slug=? LIMIT 1'); $q->execute([$orgId,$candidate]); if(!$q->fetch()){ $slug=$candidate; break; } $suffix='-'.$n; $slug=substr($baseSlug,0,180-strlen($suffix)).$suffix; $candidate=$slug; } } else { $q=$db->prepare('SELECT id FROM tours WHERE organization_id=? AND slug=? LIMIT 1'); $q->execute([$orgId,$slug]); if($q->fetch()) throw new RuntimeException('The public slug is already in use. Please choose a different slug.'); } $q=$db->prepare('INSERT INTO tours (organization_id,name,slug,start_date,end_date,default_fee,description,created_by) VALUES (?,?,?,?,?,?,?,?)'); $q->execute([saas_current_organization_id(),$name,$slug,$start?:null,$end?:null,$fee,$desc?:null,saas_user_id()]); $id=(int)$db->lastInsertId();$uploadedBanner=upload_tour_image('banner_upload',$id,'cover');$uploadedLogo=upload_tour_image('logo_upload',$id,'logo');if($uploadedBanner!=='')$banner=$uploadedBanner;if($uploadedLogo!=='')$logo=$uploadedLogo;
  $q=$db->prepare("INSERT INTO tour_members (tour_id,user_id,role,status) VALUES (?,?,'OWNER','ACTIVE')"); $q->execute([$id,saas_user_id()]); $settings=$db->prepare('INSERT INTO tour_settings(tour_id,setting_key,setting_value,value_type) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),value_type=VALUES(value_type)'); $settings->execute([$id,'default_transport',$transport,'STRING']); if($banner!=='')$settings->execute([$id,'banner_image',$banner,'STRING']); $settings->execute([$id,'notes','','STRING']); $settings->execute([$id,'schedule','','STRING']);$settings->execute([$id,'departure_options',json_encode($departures,JSON_UNESCAPED_UNICODE),'JSON']);$settings->execute([$id,'logo_image',$logo,'STRING']);$q=$db->prepare('INSERT INTO tour_public_pages(tour_id,status,theme_key,title,cover_image,logo_image) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE cover_image=VALUES(cover_image),logo_image=VALUES(logo_image)');$q->execute([$id,'DRAFT','classic',$name,$banner?:null,$logo?:null]);$db->commit(); saas_set_context(saas_current_organization_id(),$id); saas_audit('tour.created','tour',$id,json_encode(['name'=>$name],JSON_UNESCAPED_UNICODE)); saas_redirect('dashboard.php');
 }catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();$msg=$e->getMessage();$error=str_contains(strtolower($msg),'duplicate')||str_contains(strtolower($msg),'slug')?'Could not create tour. The public slug is already in use. Please choose a different slug.':$msg;}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create tour</title><style>body{font-family:Arial,sans-serif;background:#f5f7fb;margin:0}.box{max-width:620px;margin:50px auto;background:#fff;padding:32px;border-radius:14px;box-shadow:0 8px 30px #0001}input,textarea,button{width:100%;padding:12px;margin:7px 0 14px;box-sizing:border-box}button{cursor:pointer}.err{color:#b42318;margin:12px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:600px){.grid{grid-template-columns:1fr}}</style></head><body><main class="box"><h1>Create a tour</h1><p>Set the core trip details, default transport and dashboard banner. You can configure the operational details after creation.</p><?php if($error):?><div class="err"><?=saas_h($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><label>Tour name</label><input name="name" required><label>Public URL / slug <small>(auto-generated; you can edit it)</small></label><div style="display:flex;gap:8px;align-items:center"><input id="slug" name="slug" placeholder="kuakata-tour-2026" style="margin-bottom:0"><span style="white-space:nowrap;color:#667085;font-size:13px">/tour/...</span></div><div class="grid"><div><label>Start date</label><input type="date" name="start_date"></div><div><label>End date</label><input type="date" name="end_date"></div></div><label>Default fee</label><input type="number" step="0.01" min="0" name="default_fee" value="0"><label>Default transport</label><select name="default_transport"><option value="BUS">Bus</option><option value="TRAIN">Train</option><option value="LAUNCH">Launch / Ferry</option><option value="AIR">Air</option><option value="OTHER">Other</option><option value="NONE">Not selected</option></select><div class="grid"><div><label>Cover image upload</label><input type="file" id="bannerUpload" name="banner_upload" accept="image/jpeg,image/png,image/webp"><small id="bannerUploadStatus">Recommended 1600 × 600 px · min 1200 × 450 · max 5 MB</small></div><div><label>Logo upload</label><input type="file" id="logoUpload" name="logo_upload" accept="image/jpeg,image/png,image/webp"><small id="logoUploadStatus">Recommended 500 × 150 px · min 200 × 60 · max 5 MB</small></div></div><div style="grid-column:1/-1;margin-top:-4px;padding:10px 12px;background:#f8fafc;border:1px solid #e4e7ec;border-radius:10px;color:#667085;font-size:13px">Images are uploaded directly to your tour. The uploaded file link will be available after the tour is created.</div><label>Departure options <small>(one per line)</small></label><textarea name="departure_options" rows="4" placeholder="Dhaka&#10;Mirpur 10&#10;Uttara&#10;Farmgate"></textarea><label>Description</label><textarea name="description" rows="5"></textarea><button type="submit">Create tour</button></form></main><script>const n=document.querySelector('[name="name"]'),s=document.getElementById('slug');let slugTouched=false;s.addEventListener('input',()=>slugTouched=true);function makeSlug(v){return v.toLowerCase().trim().replace(/[^a-z0-9\s-]/g,"").replace(/\s+/g,"-").replace(/-+/g,"-").replace(/^-|-$/g,"").slice(0,179)}n.addEventListener("input",()=>{if(!slugTouched)s.value=makeSlug(n.value)});</script><script>function fileStatus(id,inputId){const i=document.getElementById(inputId),s=document.getElementById(id);if(i&&s)i.addEventListener("change",()=>{s.textContent=i.files&&i.files[0]?"Selected: "+i.files[0].name+" · will be uploaded when you create the tour":"Recommended image size shown above.";});}fileStatus("bannerUploadStatus","bannerUpload");fileStatus("logoUploadStatus","logoUpload");</script></body></html>
